            oauth_client_id: "client-1".to_string(),
            allowed_calendar_ids: vec![1, 2, 3],
            allow_availability: true,
            allow_event_titles: true,
            allow_event_details: true,
            allow_create: true,
            allow_update: true,
            allow_delete: true,
            created_at: test_time - 86400,
            last_used_at: Some(test_time - 3600),
            expires_at: None,
